import JSZip from "jszip";
import type { DocumentSource, DocumentScope, ExtractedContent, ExtractedUnit } from "./types";

export async function extractPptx(
  source: DocumentSource,
  scope?: DocumentScope
): Promise<ExtractedContent> {
  const s = scope as DocumentScope | undefined;
  const buf = Buffer.from(source.buf);
  const zip = await JSZip.loadAsync(buf);

  const slideNames: string[] = [];
  zip.forEach((relPath) => {
    if (relPath.startsWith("ppt/slides/slide") && relPath.endsWith(".xml")) {
      slideNames.push(relPath);
    }
  });
  slideNames.sort((a, b) => {
    const na = parseInt(a.replace(/\D/g, ""), 10);
    const nb = parseInt(b.replace(/\D/g, ""), 10);
    return na - nb;
  });

  const allowed = new Set(s?.slideIndices ?? []);

  const units: ExtractedUnit[] = [];
  for (let i = 0; i < slideNames.length; i++) {
    const slideNum = i + 1;
    if (allowed.size > 0 && !allowed.has(slideNum)) continue;

    const xml = await zip.file(slideNames[i])?.async("text");
    if (!xml) continue;

    const texts: string[] = [];
    const matches = xml.matchAll(/<a:t>([^<]*)<\/a:t>/g);
    for (const m of matches) {
      const t = m[1].trim();
      if (t) texts.push(t);
    }

    const text = texts.join("\n");
    if (!text) continue;

    units.push({
      id: `slide:${slideNum}`,
      kind: "slide",
      location: `第 ${slideNum} 页幻灯片`,
      index: i,
      text,
      children: texts.map((t, idx) => ({ label: `文本框 ${idx + 1}`, text: t })),
    });
  }

  const summary = `PPT「${source.name}」共 ${slideNames.length} 页幻灯片,提取 ${units.length} 页`;

  return {
    format: "pptx",
    name: source.name,
    units,
    summary,
    meta: {
      slideCount: slideNames.length,
    },
  };
}

import type { DocumentSource, DocumentScope, ExtractedContent, ExtractedUnit } from "./types";

export async function extractText(
  source: DocumentSource,
  _scope?: DocumentScope
): Promise<ExtractedContent> {
  const text = Buffer.from(source.buf).toString("utf-8");
  const paragraphs = text
    .split(/\r?\n/)
    .map((p) => p.trim())
    .filter((p) => p.length > 0);

  const units: ExtractedUnit[] = paragraphs.map((p, idx) => ({
    id: `para:${idx + 1}`,
    kind: "paragraph",
    location: `段落 ${idx + 1}`,
    index: idx,
    text: p,
  }));

  return {
    format: "text",
    name: source.name,
    units,
    summary: `文本「${source.name}」共 ${units.length} 段, ${text.length} 字`,
    meta: {
      charCount: text.length,
    },
  };
}

import type { DocumentFormat, DocumentScope } from "../documents/types";

export interface ProofreadDocument {
  id: string;
  name: string;
  format: DocumentFormat;
  scope: DocumentScope;
}

export interface ProofreadConfig {
  baselines: ProofreadDocument[];
  targets: ProofreadDocument[];
  relationship: "translation" | "same_lang_version" | "template_fill" | string;
  pairingMode: "row" | "key" | "auto";
  dimensions: string[];
  standards?: { name: string; text: string; roles: string[] }[];
}

export function defaultScope(format: DocumentFormat): DocumentScope {
  switch (format) {
    case "excel":
      return { format: "excel", sheet: "" };
    case "word":
    case "pdf":
      return { format };
    case "pptx":
      return { format: "pptx" };
    case "text":
    default:
      return { format: "text" };
  }
}

export function validateScope(scope: DocumentScope): string | null {
  switch (scope.format) {
    case "excel":
      if (!scope.sheet) return "Excel 范围必须选择 sheet";
      if (scope.range) {
        const ok = /^[A-Za-z]+\d+(:[A-Za-z]+\d+)?$/.test(scope.range);
        if (!ok) return "Excel 范围格式应为 A1:B10";
      }
      return null;
    case "word":
    case "pdf":
      if (
        scope.pageStart !== undefined &&
        scope.pageEnd !== undefined &&
        scope.pageStart > scope.pageEnd
      ) {
        return "起始页不能大于结束页";
      }
      return null;
    case "pptx":
      return null;
    case "text":
      return null;
    default:
      return "未知格式";
  }
}

export function scopeToString(scope: DocumentScope): string {
  switch (scope.format) {
    case "excel": {
      const range = scope.range ? `(${scope.range})` : "";
      const key = scope.keyCol ? `·关键列${scope.keyCol}` : "";
      return `Excel:${scope.sheet}${range}${key}`;
    }
    case "word":
    case "pdf": {
      if (scope.pageStart || scope.pageEnd) {
        return `${scope.format === "word" ? "Word" : "PDF"}:第 ${scope.pageStart ?? 1}-${scope.pageEnd ?? "末"} 页`;
      }
      return scope.format === "word" ? "Word:全文" : "PDF:全文";
    }
    case "pptx":
      if (scope.slideIndices?.length) return `PPT:第 ${scope.slideIndices.join(",")} 页`;
      return "PPT:全部幻灯片";
    case "text":
      return "文本:全文";
  }
}

export function normalizeDimensions(
  enabled: string[],
  relationship: string
): string[] {
  const chosen = new Set(enabled);
  chosen.add("accuracy");
  chosen.add("scope");
  if (relationship === "template_fill") chosen.delete("sync");
  return Array.from(chosen);
}

export const PROOFREAD_DIMENSIONS = [
  { key: "accuracy", label: "准确性", required: true },
  { key: "scope", label: "范围与基准", required: true },
  { key: "consistency", label: "一致性", required: false },
  { key: "sync", label: "同步", required: false },
  { key: "tone", label: "语气", required: false },
];

export const PROOFREAD_RELATIONSHIPS = [
  { key: "translation", label: "翻译(中→外)" },
  { key: "same_lang_version", label: "同语言不同版本" },
  { key: "template_fill", label: "模板 vs 填写版" },
];

import type { ExtractedContent, ExtractedUnit } from "../documents/types";
import type { ProofreadFinding } from "../tools/types";

export interface AlignedPair {
  id: string;
  baseline?: ExtractedUnit;
  target?: ExtractedUnit;
}

export function renderUnit(unit: ExtractedUnit | undefined): string {
  if (!unit) return "(空)";
  let out = `[${unit.location}] ${unit.text}`;
  if (unit.children?.length) {
    out += "\n  " + unit.children.map((c) => `${c.label}=${c.text}`).join("\n  ");
  }
  return out;
}

export function renderPairs(pairs: AlignedPair[]): string {
  if (!pairs.length) return "(无配对)";
  return pairs
    .map((p, i) => {
      const baseline = renderUnit(p.baseline).replace(/\n/g, "\n  ");
      const target = renderUnit(p.target).replace(/\n/g, "\n  ");
      return `配对#${i + 1} id=${p.id}\n母本:\n  ${baseline}\n目标:\n  ${target}`;
    })
    .join("\n\n");
}

export function renderContent(content: ExtractedContent): string {
  return `${content.summary}\n\n${content.units.map((u) => renderUnit(u)).join("\n\n")}`;
}

export const DIMENSION_LABELS: Record<string, string> = {
  accuracy: "准确性",
  sync: "同步",
  consistency: "一致性",
  scope: "范围与基准",
  tone: "语气",
};

export function buildDimensionSystem(
  dimension: string,
  relationship: string,
  kbContext: string
): string {
  const dimLabel = DIMENSION_LABELS[dimension] ?? dimension;
  return `你是一名严谨的跨文档校对专家。当前只审查「${dimLabel}」维度。

源-目标关系说明:${relationship}

只读纪律:你只做判断,绝不建议改写母本;母本是唯一事实依据。

审查要求:
- 只输出 ${dimLabel} 维度下的差异。
- 每条差异必须引用母本(或授权标准)的确切片段 + 位置作为证据。
- 聚类:同一子类型、同一根因的多个位置合并为一条 finding,在 location 里列出所有坐标(用 / 分隔)。
- 严重度(后果)与置信度(确定性)独立评估。
- 没有差异就返回空 findings 数组。

品牌知识库判据:
${kbContext}

输出严格 JSON,结构见用户消息。`;
}

export function buildDimensionUser(
  dimension: string,
  pairs: AlignedPair[],
  baselineContent: ExtractedContent,
  targetContent: ExtractedContent
): string {
  return `请审查以下配对单元在「${DIMENSION_LABELS[dimension] ?? dimension}」维度上的差异。

== 配对单元(已对齐) ==
${renderPairs(pairs)}

== 母本全范围(用于横向一致性/格式判断) ==
${renderContent(baselineContent)}

== 目标全范围 ==
${renderContent(targetContent)}

== 输出 JSON schema ==
{
  "findings": [{
    "file": "目标文件名",
    "location": "目标位置坐标;多个用 / 分隔",
    "original": "目标原文关键片段",
    "suggestion": "建议/处理",
    "dimension": "${DIMENSION_LABELS[dimension] ?? dimension}",
    "subtype": "子类型",
    "severity": "高|中|低|可接受差异",
    "confidence": "高|中|低",
    "evidence": "依据:引用母本或标准片段+坐标"
  }]
}

只输出 JSON,不要解释。`;
}

export function buildVerifySystem(): string {
  return `你是一名校对复审员。下面是一批候选差异,请做最终校验:
1. 剔除证据不足、无法引用母本确切片段的项。
2. 合并重复或同一根因的项,location 聚类。
3. 对低置信度但确实可疑的项,保留并标记 confidence 为「低」。
4. 没有问题的项直接删除。
5. 绝不编造新的 finding。

输出严格 JSON,结构见用户消息。`;
}

export function buildVerifyUser(findings: ProofreadFinding[]): string {
  return `请复审以下候选差异:

${JSON.stringify(findings, null, 2)}

== 输出 JSON schema ==
{
  "findings": [同输入结构但已过滤/合并],
  "removed": ["移除原因1", "移除原因2"]
}

只输出 JSON,不要解释。`;
}

export function buildScopeSuggestSystem(): string {
  return `你是一名文档结构化分析助手。请阅读文档摘要和结构,建议最适合作为校对范围的区域。

规则:
- 对 Excel:建议应校对的 sheet 名,必要时建议 A1 范围和关键列。
- 对 Word/PDF:建议应校对的页码范围。
- 对 PPT:建议应校对的幻灯片页码。
- 如果不确定,建议全文。
- 只输出 JSON,不要解释。`;
}

export function buildScopeSuggestUser(content: ExtractedContent): string {
  return `文档摘要:${content.summary}\n\n前 10 个单元:\n${content.units
    .slice(0, 10)
    .map((u) => `[${u.location}] ${u.text.slice(0, 200)}`)
    .join("\n")}\n\n请输出建议范围 JSON:\n{
  "reason": "建议理由",
  "scope": { "format": "${content.format}", ...格式对应字段 }
}`;
}

import { loadKb } from "../kb/store";
import { completeJson } from "../llm";
import type { ProofreadFinding, ProofreadResult } from "../tools/types";
import { extractDocument } from "../documents/extract";
import type {
  DocumentSource,
  ExtractedContent,
  ExtractedUnit,
} from "../documents/types";
import type { ProofreadConfig, ProofreadDocument } from "./scope";
import {
  buildDimensionSystem,
  buildDimensionUser,
  buildVerifySystem,
  buildVerifyUser,
  buildScopeSuggestSystem,
  buildScopeSuggestUser,
  renderContent,
  type AlignedPair,
} from "./prompts";

export interface AgentDriver {
  completeJson: <T>(opts: {
    system: string;
    user: string;
    mode?: string;
    maxTokens?: number;
  }) => Promise<T>;
}

export const defaultAgentDriver: AgentDriver = { completeJson };

export type ProofreadEvent =
  | { type: "step"; step: string; message: string }
  | { type: "ingested"; documentId: string; summary: string }
  | { type: "aligned"; pairCount: number; unmatchedBaseline: number; unmatchedTarget: number }
  | { type: "dimension_started"; dimension: string }
  | { type: "dimension_done"; dimension: string; count: number }
  | { type: "verify_started"; total: number }
  | { type: "verify_done"; kept: number; removed: number }
  | { type: "error"; message: string }
  | { type: "complete"; result: ProofreadResult };

export interface EngineOptions {
  config: ProofreadConfig;
  buffers: Map<string, Buffer>;
  driver?: AgentDriver;
  mode?: string;
}

export async function* runProofreadEngine(
  opts: EngineOptions
): AsyncGenerator<ProofreadEvent> {
  const { config, buffers, driver = defaultAgentDriver, mode } = opts;

  try {
    // 1. Ingest
    yield { type: "step", step: "ingest", message: "正在解析文档…" };
    const baselineContents: ExtractedContent[] = [];
    for (const doc of config.baselines) {
      const buf = buffers.get(doc.id);
      if (!buf) throw new Error(`缺少母本文件:${doc.name}`);
      const content = await extractDocument(
        { name: doc.name, format: doc.format, buf },
        doc.scope
      );
      baselineContents.push(content);
      yield { type: "ingested", documentId: doc.id, summary: content.summary };
    }

    const targetContents: ExtractedContent[] = [];
    for (const doc of config.targets) {
      const buf = buffers.get(doc.id);
      if (!buf) throw new Error(`缺少目标文件:${doc.name}`);
      const content = await extractDocument(
        { name: doc.name, format: doc.format, buf },
        doc.scope
      );
      targetContents.push(content);
      yield { type: "ingested", documentId: doc.id, summary: content.summary };
    }

    const baselinePool = mergeContents(baselineContents, "母本池");

    // 2. Align + Inspect per target
    const kbContext = await buildKbContext(config.standards);
    let allFindings: ProofreadFinding[] = [];

    for (const target of targetContents) {
      yield {
        type: "step",
        step: "align",
        message: `正在对齐「${target.name}」…`,
      };
      const pairs = alignContents(baselinePool, target, config.pairingMode);
      yield {
        type: "aligned",
        pairCount: pairs.length,
        unmatchedBaseline: pairs.filter((p) => !p.baseline).length,
        unmatchedTarget: pairs.filter((p) => !p.target).length,
      };

      for (const dimension of config.dimensions) {
        yield { type: "dimension_started", dimension };
        const raw = await driver.completeJson<{ findings?: unknown[] }>({
          system: buildDimensionSystem(dimension, config.relationship, kbContext),
          user: buildDimensionUser(dimension, pairs, baselinePool, target),
          mode,
          maxTokens: 4000,
        });
        const findings = (raw.findings ?? []).map((f) =>
          normalizeFinding(f as Record<string, unknown>, target.name)
        );
        allFindings.push(...findings);
        yield {
          type: "dimension_done",
          dimension,
          count: findings.length,
        };
      }
    }

    // 3. Verify
    yield {
      type: "step",
      step: "verify",
      message: `正在复审 ${allFindings.length} 条候选差异…`,
    };
    yield { type: "verify_started", total: allFindings.length };
    let verified = allFindings;
    let removedCount = 0;
    if (allFindings.length > 0) {
      const verifyRaw = await driver.completeJson<{
        findings?: unknown[];
        removed?: unknown[];
      }>({
        system: buildVerifySystem(),
        user: buildVerifyUser(allFindings),
        mode,
        maxTokens: 4000,
      });
      const targetName = config.targets[0]?.name ?? "目标";
      verified = (verifyRaw.findings ?? []).map((f) =>
        normalizeFinding(f as Record<string, unknown>, targetName)
      );
      removedCount =
        (verifyRaw.removed?.length as number | undefined) ??
        Math.max(0, allFindings.length - verified.length);
    }
    yield {
      type: "verify_done",
      kept: verified.length,
      removed: removedCount,
    };

    // 4. Report
    const result: ProofreadResult = {
      findings: verified,
      noDifference: verified.length === 0,
      notes: `共校对 ${config.targets.length} 个目标文件,母本池含 ${baselinePool.units.length} 个单元。`,
    };
    yield { type: "complete", result };
  } catch (e) {
    yield {
      type: "error",
      message: e instanceof Error ? e.message : String(e),
    };
    yield {
      type: "complete",
      result: { findings: [], noDifference: false, notes: "校对失败" },
    };
  }
}

export async function suggestScope(
  source: DocumentSource,
  driver: AgentDriver = defaultAgentDriver,
  mode?: string
): Promise<{ reason: string; scope: Record<string, unknown> }> {
  const content = await extractDocument(source);
  const raw = await driver.completeJson<{
    reason?: string;
    scope?: Record<string, unknown>;
  }>({
    system: buildScopeSuggestSystem(),
    user: buildScopeSuggestUser(content),
    mode,
    maxTokens: 1500,
  });
  return {
    reason: raw.reason || "",
    scope: raw.scope || { format: source.format },
  };
}

function mergeContents(contents: ExtractedContent[], name: string): ExtractedContent {
  const units: ExtractedUnit[] = [];
  for (const c of contents) {
    for (const u of c.units) {
      units.push({
        ...u,
        id: `${c.name}::${u.id}`,
        location: `${c.name} / ${u.location}`,
      });
    }
  }
  return {
    format: contents[0]?.format ?? "text",
    name,
    units,
    summary: `${name}: 合并 ${contents.length} 个文档,共 ${units.length} 个单元`,
  };
}

function alignContents(
  baseline: ExtractedContent,
  target: ExtractedContent,
  mode: string
): AlignedPair[] {
  const pairs: AlignedPair[] = [];
  const unmatchedBaseline: ExtractedUnit[] = [];
  const unmatchedTarget: ExtractedUnit[] = [];

  if (mode === "key") {
    const bIndex = new Map<string, ExtractedUnit>();
    for (const u of baseline.units) {
      if (u.id.startsWith("key:")) {
        bIndex.set(u.id.slice(4), u);
      }
    }
    const matched = new Set<string>();
    for (const t of target.units) {
      const key = t.id.startsWith("key:") ? t.id.slice(4) : "";
      const b = key ? bIndex.get(key) : undefined;
      if (b) {
        matched.add(key);
        pairs.push({ id: key, baseline: b, target: t });
      } else {
        unmatchedTarget.push(t);
      }
    }
    for (const [key, b] of bIndex.entries()) {
      if (!matched.has(key)) unmatchedBaseline.push(b);
    }
  } else {
    const n = Math.min(baseline.units.length, target.units.length);
    for (let i = 0; i < n; i++) {
      pairs.push({
        id: baseline.units[i].id,
        baseline: baseline.units[i],
        target: target.units[i],
      });
    }
    unmatchedBaseline.push(...baseline.units.slice(n));
    unmatchedTarget.push(...target.units.slice(n));
  }

  for (const b of unmatchedBaseline) {
    pairs.push({ id: b.id, baseline: b });
  }
  for (const t of unmatchedTarget) {
    pairs.push({ id: t.id, target: t });
  }

  return pairs;
}

async function buildKbContext(
  extraStandards?: { name: string; text: string; roles: string[] }[]
): Promise<string> {
  const kb = await loadKb();
  const lines: string[] = [];
  if (kb.terminology.length) {
    const terms = kb.terminology
      .filter((t) => t.zh && (t.en || t.preferred))
      .slice(0, 50)
      .map((t) => `${t.zh} = ${t.en ?? t.preferred}`)
      .join("; ");
    lines.push(`统一术语:${terms}`);
  }
  if (kb.compliance.bannedPhrases.length)
    lines.push(`合规违禁词:${kb.compliance.bannedPhrases.join("、")}`);
  for (const std of kb.writingStandards) {
    lines.push(
      `书写标准「${std.name}」(角色:${std.roles.join("、")}):${std.text.slice(0, 800)}`
    );
  }
  for (const std of extraStandards ?? []) {
    lines.push(`三方标准「${std.name}」(角色:${std.roles.join("、")}):${std.text.slice(0, 800)}`);
  }
  return lines.join("\n") || "(知识库无可用判据)";
}

function normalizeFinding(
  f: Record<string, unknown>,
  targetName: string
): ProofreadFinding {
  const s = (x: unknown) =>
    typeof x === "string" ? x : x == null ? "" : String(x);
  return {
    file: s(f.file) || targetName,
    location: s(f.location),
    original: s(f.original),
    suggestion: s(f.suggestion),
    dimension: s(f.dimension),
    subtype: s(f.subtype),
    severity: s(f.severity),
    confidence: s(f.confidence),
    evidence: s(f.evidence),
  };
}

import type { ProofreadConfig, ProofreadDocument } from "./scope";

export interface SerializableSession {
  baselines: ProofreadDocument[];
  targets: ProofreadDocument[];
  relationship: string;
  pairingMode: string;
  dimensions: string[];
  standards?: { name: string; text: string; roles: string[] }[];
  updatedAt: number;
}

export function serializeSession(config: ProofreadConfig): SerializableSession {
  return {
    baselines: config.baselines.map((b) => ({ ...b })),
    targets: config.targets.map((t) => ({ ...t })),
    relationship: config.relationship,
    pairingMode: config.pairingMode,
    dimensions: config.dimensions,
    standards: config.standards,
    updatedAt: Date.now(),
  };
}

export function deserializeSession(raw: unknown): ProofreadConfig | null {
  if (!raw || typeof raw !== "object") return null;
  const r = raw as Record<string, unknown>;
  if (!Array.isArray(r.baselines) || !Array.isArray(r.targets)) return null;
  return {
    baselines: r.baselines as ProofreadDocument[],
    targets: r.targets as ProofreadDocument[],
    relationship: typeof r.relationship === "string" ? r.relationship : "translation",
    pairingMode:
      r.pairingMode === "row" || r.pairingMode === "key" || r.pairingMode === "auto"
        ? r.pairingMode
        : "auto",
    dimensions: Array.isArray(r.dimensions) ? (r.dimensions as string[]) : ["accuracy", "scope"],
    standards: Array.isArray(r.standards) ? (r.standards as { name: string; text: string; roles: string[] }[]) : undefined,
  };
}

export function newSessionId(): string {
  return `pr-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`;
}

